<template>
  <section class="planned-services" aria-label="Client service history">
    <header><div><h3>{{ clientName || 'Client' }} · service history</h3><p>Scheduled visits appear here alongside documentation and claims for this patient.</p></div><button :disabled="loading" @click="load">Refresh history</button></header>
    <p v-if="error" role="alert">{{ error }}</p><p v-if="loading" role="status">Loading service history…</p>
    <div v-else class="table-scroll"><table v-if="items.length"><thead><tr><th>Date of service</th><th>Service</th><th>Clinician</th><th>Stage</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.key"><td>{{ billingDate(item.date_of_service) }}</td><td>{{ item.service_code || 'Not recorded' }}</td><td>{{ item.provider_name || 'Not recorded' }}</td><td>{{ item.stage === 'scheduled' ? 'Scheduled' : claimStatusLabel(workStage(item)) }}</td><td><button v-if="item.stage !== 'scheduled'" @click="emit('open-work-item',item)">{{ workItemTitle(item) }} →</button></td></tr></tbody></table><p v-else-if="!error">No service history is available for this patient.</p></div>
    <nav v-if="total > 30 || page > 1" class="pagination" aria-label="Client service history pages"><span>Page {{ page }} of {{ Math.max(1,Math.ceil(total/30)) }}</span><button :disabled="loading || page <= 1" @click="page--">Previous</button><button :disabled="loading || page * 30 >= total" @click="page++">Next</button></nav>
  </section>
</template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';
import api from '../../services/api';
import {billingDate,claimStatusLabel,workStage,workItemTitle} from '../../utils/billingWorkspace.js';
const props=defineProps({agencyId:{type:Number,required:true},clientId:{type:Number,required:true},clientName:{type:String,default:''}});
const emit=defineEmits(['open-work-item']);
const items=ref([]),loading=ref(false),error=ref(''),total=ref(0),page=ref(1);let seq=0;
async function load(){const current=++seq;items.value=[];error.value='';loading.value=true;try{const [work,planned]=await Promise.all([api.get('/medical-billing/workspace',{params:{agencyId:props.agencyId,clientId:props.clientId,status:'all',sortBy:'date_of_service',direction:'desc',page:page.value},skipGlobalLoading:true}),api.get('/medical-billing/planned-services',{params:{agencyId:props.agencyId,clientId:props.clientId},skipGlobalLoading:true})]);if(current!==seq)return;const linked=(work.data.claims||[]).filter(row=>Number(row.client_id)===Number(props.clientId));const sessions=new Set(linked.map(row=>Number(row.clinical_session_id)).filter(Boolean));const scheduled=page.value===1?(planned.data.items||[]).filter(row=>Number(row.clientId)===Number(props.clientId)&&!row.noteId&&!row.signedAt&&!sessions.has(Number(row.sessionId))&&(row.source==='appointment'||row.stage==='scheduled')).map(row=>({...row,key:row.key||`scheduled:${row.appointmentId||row.sessionId}`,date_of_service:row.serviceDate||row.startAt,service_code:row.serviceCode,provider_name:row.providerName,stage:'scheduled'})):[];items.value=[...scheduled,...linked].sort((a,b)=>String(b.date_of_service||'').localeCompare(String(a.date_of_service||'')));total.value=Number(work.data.total||0);}catch(e){if(current===seq)error.value=e.response?.data?.error?.message||'Client service history could not be loaded.';}finally{if(current===seq)loading.value=false;}}
watch(()=>[props.agencyId,props.clientId],()=>{page.value=1;load();},{immediate:true});watch(page,load);onBeforeUnmount(()=>seq++);
</script>
<style scoped>
.planned-services{border:1px solid var(--border-color,#dce5ed);border-radius:10px;background:var(--bg-primary,#fff);padding:16px;margin:16px 0}.planned-services header,.pagination{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.planned-services h3{margin-top:0}.planned-services p{color:var(--text-secondary,#586a80);line-height:1.5}.table-scroll{overflow:auto}table{width:100%;text-align:left;border-collapse:collapse;font-size:13px}th,td{padding:10px;border-bottom:1px solid #e7edf3}button{cursor:pointer;padding:7px 10px;border:1px solid #c9d9e8;background:transparent;border-radius:7px;color:var(--primary-color,#1677bc);font:inherit}.pagination{margin-top:12px;font-size:12px}
</style>
